\foreach \c in {1,2,3,4} { \draw (-0.1,\c)--(0.1,\c); \node[left,font=\scriptsize] at (-0.12,\c) {$\c$}; }
\draw[dashed,gray] (-1.5,-1.5)--(2.5,-1.5)--(2.5,0.5);
\fill (2.5,0.5) circle (2.2pt);
\node[above right,font=\footnotesize] at (2.5,0.5) {$P$};
\end{tikzpicture}
[/tikz]

